    print('per_mode: raw moments, full F0 cross moments and variance constants remain distinct')
    print('per_block: full old/battery/reference output; vector eta and unhalved trace2eta')
    print('lattice_wide: finite mean sharpness only; no generic-fault, native-resource or retained-audit claim')
    return 0

